        color: getSeriesColor(theme, i),
        type: 'line' as const,
        width: 1.5,
        spanGaps: false,
      })),
    },
    libraryConfig: {
      chart: {
        size: undefined,
        series: {type: 'line', spanGaps: false},
      },
      axes: {
        y: {
